from functools import partial, singledispatch, wraps

def traced(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        return function(*args, **kwargs)
    return wrapper

@traced
def greet(name):
    """Create a greeting."""
    return f'hello {name}'

assert greet('Ada') == 'hello Ada'
assert greet.__name__ == 'greet'
assert greet.__doc__ == 'Create a greeting.'
assert greet.__wrapped__('Ada') == 'hello Ada'
binary = partial(int, base=2)
assert binary('101') == 5
assert binary('11', base=10) == 11  # 调用处可覆盖预先绑定的关键字

@singledispatch
def kind(value):
    return 'object'

@kind.register(int)
def _(value):
    return 'integer'

assert kind(1) == kind(True) == 'integer'
assert kind('1') == 'object'

@kind.register(bool)
def _(value):
    return 'boolean'

assert kind(True) == 'boolean'
assert kind(1) == 'integer'
print('functools-dispatch: metadata, override, inheritance, specialization')

import subprocess
import sys

result = subprocess.run(
    [sys.executable, '-c', 'import sys; print(sys.argv[1])', 'a b; c'],
    capture_output=True, text=True, encoding='utf-8', check=True, timeout=5,
)
assert result.stdout == 'a b; c\n'
assert result.stderr == '' and result.returncode == 0

try:
    subprocess.run(
        [sys.executable, '-c', "import sys; sys.stderr.write('invalid'); sys.exit(2)"],
        capture_output=True, text=True, check=True, timeout=5,
    )
except subprocess.CalledProcessError as error:
    assert error.returncode == 2 and error.stderr == 'invalid'
else:
    raise AssertionError('nonzero exit was accepted')

try:
    subprocess.run([sys.executable, '-c', 'import time; time.sleep(10)'], timeout=0.5)
except subprocess.TimeoutExpired:
    pass  # run 已终止并等待这个直接子进程
else:
    raise AssertionError('expected timeout')

with subprocess.Popen(
    [sys.executable, '-c', 'import time; time.sleep(10)'],
    stdout=subprocess.PIPE, stderr=subprocess.PIPE,
) as process:
    try:
        process.communicate(timeout=0.5)
    except subprocess.TimeoutExpired:
        process.kill()       # communicate 超时不会替我们终止它
        process.communicate()  # 完成管道读取并等待回收
    else:
        raise AssertionError('expected communicate timeout')
    assert process.returncode is not None
print('subprocess: literal, nonzero, run timeout, communicate cleanup')

from enum import Flag, StrEnum, auto

class State(StrEnum):
    PENDING = 'pending'
    SHIPPED = 'shipped'
    CANCELLED = 'cancelled'

def parse_state(raw):
    if not isinstance(raw, str):
        raise TypeError('state must be text')
    return State(raw)

def ship(state):
    if not isinstance(state, State):
        raise TypeError('convert input to State first')
    if state is not State.PENDING:
        raise ValueError('only pending orders may ship')
    return State.SHIPPED

assert ship(parse_state('pending')) is State.SHIPPED
for action, expected in [
    (lambda: parse_state('unknown'), ValueError),
    (lambda: parse_state(1), TypeError),
    (lambda: ship('pending'), TypeError),
    (lambda: ship(State.SHIPPED), ValueError),
    (lambda: ship(State.CANCELLED), ValueError),
]:
    try:
        action()
    except expected:
        pass
    else:
        raise AssertionError('invalid state or transition accepted')

class Permission(Flag):
    READ = auto()
    WRITE = auto()

granted = Permission.READ | Permission.WRITE
assert (granted & Permission.READ) == Permission.READ
assert (Permission.READ & Permission.WRITE) == Permission(0)
print('enum-transition: input boundary, state rule, flags')
